import{_ as t,o,c as r,a3 as a}from"./chunks/framework.DQ-7HQaQ.js";const u=JSON.parse('{"title":"Portfolio, documentation and dev/prod application hosting","description":"","frontmatter":{},"headers":[],"relativePath":"project/hosting.md","filePath":"project/hosting.md","lastUpdated":1794374806000}'),i={name:"project/hosting.md"};function n(d,e,s,c,l,h){return o(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="portfolio-documentation-and-dev-prod-application-hosting" tabindex="-1">Portfolio, documentation and dev/prod application hosting <a class="header-anchor" href="#portfolio-documentation-and-dev-prod-application-hosting" aria-label="Permalink to &quot;Portfolio, documentation and dev/prod application hosting&quot;">​</a></h1><p><strong>Owner-selected layout · November 10, 2026.</strong> Configuration/code preparation is separate from account changes, registry publication and live deployment. No DNS or server change is established by this document.</p><h2 id="selected-addresses" tabindex="-1">Selected addresses <a class="header-anchor" href="#selected-addresses" aria-label="Permalink to &quot;Selected addresses&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Surface</th><th>Address</th><th>Target</th></tr></thead><tbody><tr><td>Portfolio</td><td><code>keithwilliams.org</code></td><td><code>kaw393939/kaw393939.github.io</code> on GitHub Pages</td></tr><tr><td>Portfolio alternate</td><td><code>www.keithwilliams.org</code></td><td>GitHub Pages, redirect to the chosen apex</td></tr><tr><td>Research application production</td><td><code>rag.keithwilliams.org</code></td><td>Verified DigitalOcean application host</td></tr><tr><td>Research application development</td><td><code>dev-rag.keithwilliams.org</code></td><td>Isolated, access-controlled development route</td></tr><tr><td>Project documentation</td><td><code>kaw393939.github.io/is373-rag/</code> initially</td><td>This repository&#39;s static Pages output</td></tr></tbody></table><p>Use <code>dev-rag</code>, not <code>dev_rag</code>, as the HTTPS hostname. Hostname syntax uses letters, digits and hyphens; DNS underscores used for service/TXT labels do not make an underscore a suitable web hostname. <a href="https://www.rfc-editor.org/rfc/rfc1123#section-2.1" target="_blank" rel="noreferrer">RFC 1123</a>.</p><p>This replaces earlier <code>ordo</code> / <code>ordo-qa</code> recommendations for this project. A portfolio custom domain may also change the inherited project-Pages origin; verify the actual documentation URL before changing <code>DOCS_ORIGIN</code> or public links. Keep <code>/is373-rag/</code> as the project base. Never point the interactive application subdomains at GitHub Pages.</p><h2 id="current-execution-boundary" tabindex="-1">Current execution boundary <a class="header-anchor" href="#current-execution-boundary" aria-label="Permalink to &quot;Current execution boundary&quot;">​</a></h2><p>Safari access failed because the Browser connection requires the originating browser context. The logged-in GoDaddy, Docker Hub and DigitalOcean sessions could not be inspected. No account write, DNS edit, registry creation, server authentication or live application deployment is claimed. Public DNS probes from the isolated authoring workspace also failed at local resolution, which does <strong>not</strong> establish that the domains or server are down.</p><p>The private server manual holds the previous provider inventory and recovery procedure. It does not prove current authenticated shell access or spare host capacity. Do not reset root, change boot mode or modify SSH/firewalls merely to work around the connection limitation.</p><h2 id="portfolio-cutover" tabindex="-1">Portfolio cutover <a class="header-anchor" href="#portfolio-cutover" aria-label="Permalink to &quot;Portfolio cutover&quot;">​</a></h2><p>Capture the authoritative zone and current GitHub Pages configuration first. Domain registration at GoDaddy does not establish which provider currently hosts DNS. Preserve MX, SPF, DKIM, DMARC, other TXT/service records and unrelated subdomains. Review conflicting A/AAAA/CNAME records and CAA restrictions without changing them blindly.</p><ol><li>Verify ownership of <code>keithwilliams.org</code> in the GitHub account using GitHub&#39;s generated TXT name/value. Do not invent the verification token. Retain this record after verification.</li><li>Inspect the portfolio publisher. It currently builds into a <code>gh-pages</code> branch; source changes alone do not publish it. Prepare <code>docs/public/CNAME</code> containing only <code>keithwilliams.org</code> so future builds preserve the domain. Update <code>docs/.vitepress/site.ts</code> and canonical/sitemap checks at cutover.</li><li>Set the portfolio repository&#39;s Pages custom domain to <code>keithwilliams.org</code> before pointing DNS at Pages. Preserve its branch/source setting.</li><li>Apply only the reviewed website record changes in the authoritative zone. Do not change nameservers or buy hosting.</li><li>Verify DNS, HTTPS, <code>www</code> redirect, portfolio assets, contact link and existing project URLs. Enable Enforce HTTPS when its certificate is available. Publish again and prove the CNAME survived.</li></ol><h3 id="desired-records-—-not-an-exported-current-zone" tabindex="-1">Desired records — not an exported current zone <a class="header-anchor" href="#desired-records-—-not-an-exported-current-zone" aria-label="Permalink to &quot;Desired records — not an exported current zone&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Type</th><th>Name</th><th>Desired value</th><th>Gate</th></tr></thead><tbody><tr><td>A</td><td><code>@</code></td><td><code>185.199.108.153</code></td><td>Verified portfolio Pages setup</td></tr><tr><td>A</td><td><code>@</code></td><td><code>185.199.109.153</code></td><td>Same</td></tr><tr><td>A</td><td><code>@</code></td><td><code>185.199.110.153</code></td><td>Same</td></tr><tr><td>A</td><td><code>@</code></td><td><code>185.199.111.153</code></td><td>Same</td></tr><tr><td>CNAME</td><td><code>www</code></td><td><code>kaw393939.github.io</code></td><td>No conflicting <code>www</code> record</td></tr><tr><td>TXT</td><td>GitHub-provided name</td><td>GitHub-provided verification token</td><td>Obtain from authenticated GitHub</td></tr><tr><td>A</td><td><code>dev-rag</code></td><td>Reverified application-server IPv4</td><td>Isolated route, access and TLS plan ready</td></tr><tr><td>A</td><td><code>rag</code></td><td>Reverified application-server IPv4</td><td>Accepted production candidate and rollback ready</td></tr></tbody></table><p>Do not apply the server IP from a historical inventory without rechecking it. Do not add wildcard DNS. For rollback, record prior values/TTLs before editing; reverse only this change set. DNS propagation is not instantaneous.</p><h2 id="welcome-image-and-environment-separation" tabindex="-1">Welcome image and environment separation <a class="header-anchor" href="#welcome-image-and-environment-separation" aria-label="Permalink to &quot;Welcome image and environment separation&quot;">​</a></h2><p>The <a href="https://github.com/kaw393939/is373-rag/tree/main/welcome" target="_blank" rel="noreferrer">Svelte welcome package</a> is a deployment scaffold with repository/docs links and an explicit <strong>Backend not connected</strong> notice. It does not implement or simulate a working research assistant. The eventual product remains the SvelteKit/TypeScript client and Rust services described in <a href="./system">system</a>.</p><p>The <a href="https://github.com/kaw393939/is373-rag/tree/main/deploy" target="_blank" rel="noreferrer">deployment definitions</a> use separate Compose projects and exact host rules, a non-root read-only container, limited resources, and the existing proxy. Development requires a verified access-control middleware. No database, model credential or user data is needed for this first welcome image.</p><p>The Welcome CI workflow tests source and a Linux amd64 image. A separate manual publish workflow pushes the <strong>same tested image</strong> to a confirmed public Docker Hub repository. Source commit, CI artifact, registry push, host deployment and public HTTPS verification are distinct receipts. Docker Hub credentials remain in GitHub secrets; no credentials go in documentation or browser bundles.</p><h2 id="research-publication-boundary" tabindex="-1">Research publication boundary <a class="header-anchor" href="#research-publication-boundary" aria-label="Permalink to &quot;Research publication boundary&quot;">​</a></h2><p>Local authoring publishes a validated immutable library revision. The future cloud application reads that snapshot and stores conversations/run state separately. It does not sync live SQLite files or become a second canonical graph writer. Real hosted generation needs a selected provider/worker, data policy and usage controls. Missing capabilities must be visible.</p><h2 id="official-references" tabindex="-1">Official references <a class="header-anchor" href="#official-references" aria-label="Permalink to &quot;Official references&quot;">​</a></h2><p><a href="https://docs.github.com/en/pages/configuring-a-custom-domain-for-your-github-pages-site/managing-a-custom-domain-for-your-github-pages-site" target="_blank" rel="noreferrer">GitHub custom domains</a>, <a href="https://docs.github.com/en/pages/configuring-a-custom-domain-for-your-github-pages-site/verifying-your-custom-domain-for-github-pages" target="_blank" rel="noreferrer">domain verification</a>, <a href="https://www.godaddy.com/help/manage-dns-records-680" target="_blank" rel="noreferrer">GoDaddy DNS</a>, <a href="https://docs.docker.com/docker-hub/repos/create/" target="_blank" rel="noreferrer">Docker Hub repository creation</a>, <a href="https://docs.docker.com/build/ci/github-actions/" target="_blank" rel="noreferrer">Docker build actions</a>, <a href="https://svelte.dev/docs/svelte/svelte-compiler" target="_blank" rel="noreferrer">Svelte compiler</a>, <a href="https://12factor.net/build-release-run" target="_blank" rel="noreferrer">twelve-factor build/release/run</a>.</p><p>Recheck the provider UI at execution time. The <a href="https://github.com/kaw393939/373_hosting" target="_blank" rel="noreferrer">hosting studio</a> is an existing-host reference, not permission to overwrite infrastructure. Account-wide billing/domain-renewal changes remain in the private operations record, not this public teaching site.</p>',24)])])}const g=t(i,[["render",n]]);export{u as __pageData,g as default};
